// akantu-rs: parity of the clean-room complex division (std::complex<double>
// division as used by Eigen 3.4.0 in Akantu's aka_types.hh, EPFL/LSMS) with
// black-box oracle results (D-030 amendment).

//! Bit-level parity of [`Complex::quotient`] with the oracle's
//! `std::complex<double>` division on inputs that discriminate every rule of
//! the clean-room model: fixture `fixtures/dense/complex_div_cleanroom.txt`,
//! generated by `oracle/probes/dense/complex_cleanroom/run.sh` (black-box
//! runs in `akantu-oracle:dev`; provenance in
//! `crates/akantu-linalg/src/dense/COMPLEX_CLEANROOM_LOG.md`).
//!
//! Every record must match bit for bit; two NaNs compare equal whatever their
//! sign and payload (neither C++ nor Rust specifies NaN bits). The number of
//! records whose NaN sign bits also agree is reported, not asserted.
//!
//! `bulk_oracle_file` (medium tier, opt-in) checks a large binary file of
//! oracle results when `AKANTU_CDIV_BULK` names one; produce it with
//! `oracle/probes/dense/complex_cleanroom/e27_bulk.cc` (see
//! `COMPLEX_CLEANROOM_LOG.md`, "Rust-side bulk check").

use std::collections::BTreeMap;

use akantu_linalg::dense::{Complex, ComplexDivision};

const FIXTURE: &str = include_str!("fixtures/dense/complex_div_cleanroom.txt");
const FIXTURE_X86_64: &str = include_str!("fixtures/dense/complex_div_cleanroom_x86_64.txt");
const GUARD_X86_64: &str = include_str!("fixtures/dense/complex_div_guard_x86_64.txt");

fn parse(tok: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(tok, 16).unwrap_or_else(|_| panic!("bad hex {tok}")))
}

/// Exact match (decision D-046: bit identity, or default quiet NaNs of
/// either sign; a looser "any two NaNs" match would hide payload
/// differences).
fn same(a: f64, b: f64) -> bool {
    akantu_validation::exact_eq(a, b)
}

/// Every record of a `cdivx` fixture through [`Complex::quotient_with`]:
/// (records, mismatch descriptions).
fn replay(fixture: &str, division: ComplexDivision) -> (usize, Vec<String>) {
    let mut per_tag: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    let mut mismatches = Vec::new();
    let (mut nan_records, mut nan_sign_equal) = (0usize, 0usize);
    for (i, line) in fixture.lines().enumerate() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut parts = line.split(" | ");
        let head: Vec<&str> = parts.next().unwrap_or("").split_whitespace().collect();
        assert_eq!(head.first(), Some(&"cdivx"), "line {}: bad head", i + 1);
        let tag = head.get(1).copied().unwrap_or("?").to_string();
        let input: Vec<f64> = parts
            .next()
            .unwrap_or("")
            .split_whitespace()
            .map(parse)
            .collect();
        let want: Vec<f64> = parts
            .next()
            .unwrap_or("")
            .split_whitespace()
            .map(parse)
            .collect();
        assert_eq!(
            (input.len(), want.len()),
            (4, 2),
            "line {}: bad record",
            i + 1
        );
        let z = Complex::new(input[0], input[1])
            .quotient_with(Complex::new(input[2], input[3]), division);
        let entry = per_tag.entry(tag.clone()).or_default();
        entry.0 += 1;
        if same(z.re, want[0]) && same(z.im, want[1]) {
            entry.1 += 1;
        } else {
            mismatches.push(format!(
                "line {} [{tag}] ({:e}, {:e})/({:e}, {:e}): got ({:016x}, {:016x}) want ({:016x}, {:016x})",
                i + 1,
                input[0],
                input[1],
                input[2],
                input[3],
                z.re.to_bits(),
                z.im.to_bits(),
                want[0].to_bits(),
                want[1].to_bits()
            ));
        }
        if want[0].is_nan() || want[1].is_nan() {
            nan_records += 1;
            if z.re.to_bits() >> 63 == want[0].to_bits() >> 63
                && z.im.to_bits() >> 63 == want[1].to_bits() >> 63
            {
                nan_sign_equal += 1;
            }
        }
    }
    eprintln!("{division:?}: records per tag (total, bit-identical): {per_tag:?}");
    eprintln!(
        "{division:?}: records with a NaN part: {nan_records}, NaN sign bits also equal: \
         {nan_sign_equal}"
    );
    let total: usize = per_tag.values().map(|v| v.0).sum();
    (total, mismatches)
}

fn assert_bit_for_bit(fixture: &str, division: ComplexDivision) {
    assert_bit_for_bit_n(fixture, division, 4000);
}

fn assert_bit_for_bit_n(fixture: &str, division: ComplexDivision, min_records: usize) {
    let (total, mismatches) = replay(fixture, division);
    for m in mismatches.iter().take(40) {
        eprintln!("MISMATCH {m}");
    }
    assert!(total >= min_records, "fixture unexpectedly small ({total})");
    assert!(
        mismatches.is_empty(),
        "{} mismatches out of {total} records",
        mismatches.len()
    );
}

/// The aarch64 oracle runtime ([`Complex::quotient`], the default).
#[test]
fn complex_division_matches_oracle_bit_for_bit() {
    assert_bit_for_bit(FIXTURE, ComplexDivision::Fused);
    // `quotient` and `/` are the fused runtime
    let (x, y) = (Complex::new(1.5, -0.25), Complex::new(0.75, 3.0));
    assert_eq!(x.quotient(y), x.quotient_with(y, ComplexDivision::Fused));
    assert_eq!(x / y, x.quotient(y));
}

/// The x86_64 oracle runtime ([`ComplexDivision::Unfused`], D-043): the same
/// inputs, the results of the x86_64 oracle image
/// (`fixtures/dense/complex_div_cleanroom_x86_64.txt`, generated by
/// `oracle/probes/dense/complex_cleanroom/run_x86_64.sh`; experiment E28 in
/// `COMPLEX_CLEANROOM_LOG.md` §8).
#[test]
fn complex_division_matches_x86_64_oracle_bit_for_bit() {
    assert_bit_for_bit(FIXTURE_X86_64, ComplexDivision::Unfused);
}

/// The x86_64 runtime does not up-scale a small numerator
/// part when `max(|a|, |b|)` or `max(|c|, |d|)` is exactly
/// `0x1.fffffffffffffp+970` (`fixtures/dense/complex_div_guard_x86_64.txt`:
/// 162 machine results, provenance in its header; `COMPLEX_CLEANROOM_LOG.md`
/// §9). With the former guard `2^971` every one of them differed in the sign
/// of a zero part.
#[test]
fn complex_division_matches_x86_64_guard_records() {
    let guard = f64::from_bits(0x7c9f_ffff_ffff_ffff);
    let mut at_guard = 0;
    for line in GUARD_X86_64.lines().filter(|l| l.starts_with("cdivx ")) {
        let v: Vec<f64> = line
            .split(" | ")
            .skip(1)
            .flat_map(|p| p.split_whitespace().map(parse).collect::<Vec<_>>())
            .collect();
        let ab = v[0].abs().max(v[1].abs());
        let cd = v[2].abs().max(v[3].abs());
        if ab == guard || cd == guard {
            at_guard += 1;
        }
    }
    assert_eq!(
        at_guard, 162,
        "every guard record sits at 0x1.fffffffffffffp+970"
    );
    assert_bit_for_bit_n(GUARD_X86_64, ComplexDivision::Unfused, 162);
}

/// Each fixture discriminates the runtimes: the other runtime's division
/// fails on records of both.
#[test]
fn runtimes_are_told_apart_by_the_fixtures() {
    let (_, on_x86) = replay(FIXTURE_X86_64, ComplexDivision::Fused);
    let (_, on_aarch64) = replay(FIXTURE, ComplexDivision::Unfused);
    eprintln!(
        "fused on the x86_64 records: {} mismatches; unfused on the aarch64 records: {}",
        on_x86.len(),
        on_aarch64.len()
    );
    assert!(!on_x86.is_empty() && !on_aarch64.is_empty());
}

/// Opt-in bulk check against a binary file of oracle results (six
/// little-endian `u64` per record: a, b, c, d, re, im), written by probe
/// E27. Skipped (with a note) when `AKANTU_CDIV_BULK` is not set.
#[test]
fn bulk_oracle_file() {
    let Ok(path) = std::env::var("AKANTU_CDIV_BULK") else {
        eprintln!("AKANTU_CDIV_BULK not set: bulk oracle check skipped");
        return;
    };
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"));
    assert_eq!(data.len() % 48, 0, "{path}: not a whole number of records");
    let word = |rec: &[u8; 48], k: usize| {
        let mut w = [0u8; 8];
        w.copy_from_slice(&rec[8 * k..8 * k + 8]);
        f64::from_bits(u64::from_le_bytes(w))
    };
    let (mut total, mut bad) = (0usize, 0usize);
    for rec in data.as_chunks::<48>().0 {
        let (a, b, c, d) = (word(rec, 0), word(rec, 1), word(rec, 2), word(rec, 3));
        let (re, im) = (word(rec, 4), word(rec, 5));
        let z = Complex::new(a, b).quotient(Complex::new(c, d));
        total += 1;
        if !(same(z.re, re) && same(z.im, im)) {
            if bad < 20 {
                eprintln!(
                    "MISMATCH ({a:e}, {b:e})/({c:e}, {d:e}): got ({:016x}, {:016x}) want ({:016x}, {:016x})",
                    z.re.to_bits(),
                    z.im.to_bits(),
                    re.to_bits(),
                    im.to_bits()
                );
            }
            bad += 1;
        }
    }
    eprintln!("bulk oracle check: {total} records, {bad} mismatches");
    assert_eq!(bad, 0, "{bad} mismatches out of {total} records");
}
